{
 "command": "grep -n -A3 'test-fast' Makefile; make test-fast 2>&1 | tail -40",
 "description": "Run fast test suite"
}

{
 "command": "cat tests/fxdata.py; grep -rn \"LEDGERLINE_FX_FIXTURES\" --exclude-dir=.git . ; ls tests; find . -path ./.git -prune -o -iname '*fx*' -print",
 "description": "Inspect fixture loader and env var references"
}

{
 "command": "cat docs/testing.md; ls tests/fixtures/fx; cat pytest.ini setup.cfg pyproject.toml 2>/dev/null | head -30; LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -15",
 "description": "Read testing docs and rerun with fixture env var"
}

{
 "command": "cat scripts/gen_fx_fixtures.py; cat .gitignore",
 "description": "Inspect fixture generator script"
}

{
 "command": "python scripts/gen_fx_fixtures.py && LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -15",
 "description": "Generate FX fixtures and rerun fast suite"
}

{
 "command": "cat src/billing/currency.py; git log --oneline -- src/billing/currency.py; LEDGERLINE_FX_FIXTURES=tests/fixtures/fx python -m pytest -m \"not postgres and not integration\" -q -rA 2>&1 | grep -E '^(PASSED|FAILED|ERROR)'; python -m pytest --collect-only -q 2>&1 | tail -10",
 "description": "Inspect currency module and test collection"
}

{
 "id": "01a0fcd9-8f9f-7063-928f-22ef6b3b21b7",
 "content": "Run `make test-fast` for the unit suite (skips the Postgres and network integration tests). `make test` runs everything but needs `docker compose up db` first. The FX tests also need generated fixtures: run `python scripts/gen_fx_fixtures.py` once (output is gitignored), then run with `LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast`. Without it, test_currency errors with KeyError/FileNotFoundError (see docs/testing.md)."
}

